def make_profile(owner="o", version=1):
    return {"owner": owner, "version": version}

def test_owner_match_hits_cache():
    store = {}
    calls = {"n": 0}
    def compute():
        calls["n"] += 1
        return "result"
    t = make_task("o", 1, "j", "cv")
    p = make_profile("o", 1)
    assert evaluate(store, t, p, compute) == "result"
