    assert calls["n"] == 1

def test_owner_mismatch_raises_before_side_effects():
    store = {"k": "x"}
    def compute():
        raise AssertionError("compute should not be called on mismatch")
    task = make_task(owner="bad")
    profile = make_profile("good")
    try:
        evaluate(store, task, profile, compute)
    except PermissionError:
        pass
    else:
        raise AssertionError("expected PermissionError")
    assert store == {"k": "x"}

def test_version_mismatch_returns_none_without_side_effects():
    store = {}
    calls = {"n": 0}
    def compute():
        calls["n"] += 1
        return "never"
    task = make_task(version=2)
    profile = make_profile(version=1)
    assert evaluate(store, task, profile, compute) is None
    assert calls["n"] == 0
    assert store == {}

def test_version_match_even_zero_and_none():
